def del_del(s):
    # remove every "del", but leave a "del" alone if it's followed by another "l"
    pass

solution:
def del_del(s):
    result = ""
    i = 0
    n = len(s)
    while i < n:
        if s[i:i + 3] == "del" and s[i + 3:i + 4] != "l":
            i += 3
        else:
            result += s[i]
            i += 1
    return result

